import{af as e,z as i,J as s,ab as t}from"./chunks/framework.D7T92eqb.js";const m=JSON.parse('{"title":"BLE Scanning","description":"","frontmatter":{},"headers":[],"relativePath":"devices/capabilities/ble-scanning.md","filePath":"devices/capabilities/ble-scanning.md"}'),n={name:"devices/capabilities/ble-scanning.md"};function o(d,a,r,c,p,h){return i(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792752607000"},[...a[0]||(a[0]=[t('<h1 id="ble-scanning" tabindex="-1">BLE Scanning <a class="header-anchor" href="#ble-scanning" aria-label="Permalink to &quot;BLE Scanning&quot;">​</a></h1><p>BLE scanning is a capability that allows devices to scan for nearby Bluetooth Low Energy (BLE) devices.</p><p>This can be used for a variety of applications, such as asset tracking, proximity detection, and more.</p><p>As part of BLe scanning, we collect MAC Address, RSSI, Name, and any additional advertising data that the device is broadcasting. For various known device types and advertising types this data is parsed and stored in a structured format.</p><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><p>Most of our products have BLE capability (please see individual product specifications) and will record scan data.</p><p>We also provide a variety of <a href="/docs/pr/26/devices/peripherals">BLE Tag devices</a> that work out of the box for BLE tagging applications.</p><p>When new BLE devices are seen, they are tracked within the Lightbug platform as an additional device of type <code>BleTag</code> and they can be attached to your account, and viewed in all applications (Cloud, Admin, APIs, etc).</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><h3 id="cloud-admin-app" tabindex="-1">Cloud &amp; Admin App <a class="header-anchor" href="#cloud-admin-app" aria-label="Permalink to &quot;Cloud &amp; Admin App&quot;">​</a></h3><p>Both gateways and <code>BleTag</code> devices can have their position plotted on the <a href="/docs/pr/26/apps/cloud/">Cloud App map</a>, as well as have data visualized about them, such as temperature readings, signal strength, and more.</p><p>It&#39;s also possible to <a href="/docs/pr/26/apps/cloud/reports/proximity">view proximity reports</a> based on this information, showing what devices have been near each other, and when.</p><h3 id="v3-messaging" tabindex="-1">V3 Messaging <a class="header-anchor" href="#v3-messaging" aria-label="Permalink to &quot;V3 Messaging&quot;">​</a></h3><p>Devices that make use of V3 messaging can also make use of the <a href="/docs/pr/26/apps/admin/devices/sharing">V3 share feature</a> for adhoc visualization of this data, and sharing it with others via <a href="/docs/pr/26/apps/chasm/share/">share.chasm.cloud</a> where a dedicated <a href="/docs/pr/26/apps/chasm/share/ble-scan">BLE Scan view</a> is available.</p><p>These messages can also be <a href="/docs/pr/26/apps/admin/devices/forwarding">forwarded directly into other systems</a> and viewed <a href="/docs/pr/26/apps/admin/devices/information#live">live</a> on a per device level.</p>',15)])])}const v=e(n,[["render",o]]);export{m as __pageData,v as default};
